//! Reference parity for the tiny Ouro checkpoint: every pass's hidden state,
//! exit gate and logits against `modeling_ouro.py` at the same weights.
//!
//! The fixture is generated by `tools/goldens/ouro_dump_reference.py` into the
//! gitignored `testdata/`. Absent it, the test skips (and fails under
//! `BRAIN_REQUIRE_FIXTURES`).

use std::collections::HashMap;

use ouro::model::Ouro;

fn load_golden(path: &str) -> HashMap<String, (Vec<usize>, Vec<f32>)> {
    let ts = checkpoint::safetensors::read(path).expect("read golden");
    ts.into_iter().map(|t| (t.name, (t.shape, t.data))).collect()
}

fn rel_l2(a: &[f32], b: &[f32]) -> f32 {
    let num: f64 = a.iter().zip(b).map(|(x, y)| ((*x - *y) as f64).powi(2)).sum();
    let den: f64 = b.iter().map(|y| (*y as f64).powi(2)).sum();
    (num / den.max(1e-30)).sqrt() as f32
}

fn max_abs(a: &[f32], b: &[f32]) -> f32 {
    a.iter().zip(b).map(|(x, y)| (x - y).abs()).fold(0.0, f32::max)
}

#[test]
fn tiny_checkpoint_matches_the_reference_at_every_pass() {
    let dir = brain_testutil::testdata_path("golden/ouro/tiny");
    if !dir.join("golden.safetensors").exists() {
        brain_testutil::skip("testdata/golden/ouro/tiny absent (run tools/goldens/ouro_dump_reference.py)");
        return;
    }
    let golden = load_golden(&dir.join("golden.safetensors").to_string_lossy());
    let (cfg, src) = ouro::import::open_dir(&dir.join("checkpoint")).expect("open tiny ouro checkpoint");
    assert_eq!(cfg, ouro::config::OuroConfig::tiny());

    let tokens: Vec<u32> = golden["tokens"].1.iter().map(|v| *v as u32).collect();
    let n = tokens.len() as usize;
    let t = cfg.total_ut_steps as usize;
    let d = cfg.d_model as usize;
    let v = cfg.vocab as usize;

    let model = Ouro::new(cfg.clone(), 1, n as u32, &src);
    model.set_tokens(&tokens);
    model.trunk_forward();

    for pass in 0..t {
        let want_h = &golden["hidden"].1[pass * n * d..(pass + 1) * n * d];
        let got_h = model.read_hidden(pass);
        assert!(rel_l2(&got_h, want_h) < 1e-4, "pass {pass} hidden rel_l2 {}", rel_l2(&got_h, want_h));
        assert!(max_abs(&got_h, want_h) < 2e-3, "pass {pass} hidden max_abs {}", max_abs(&got_h, want_h));

        let want_g = &golden["gates"].1[pass * n..(pass + 1) * n];
        let got_g = model.read_gate(pass);
        assert!(max_abs(&got_g, want_g) < 2e-3, "pass {pass} gate max_abs {}", max_abs(&got_g, want_g));

        model.head_forward(pass);
        let got_l = model.read_logits();
        let want_l = &golden["logits"].1[pass * n * v..(pass + 1) * n * v];
        assert!(rel_l2(&got_l, want_l) < 1e-4, "pass {pass} logits rel_l2 {}", rel_l2(&got_l, want_l));
        assert!(max_abs(&got_l, want_l) < 2e-3, "pass {pass} logits max_abs {}", max_abs(&got_l, want_l));
    }
}

#[test]
fn the_exit_rule_agrees_with_the_reference_gates() {
    let dir = brain_testutil::testdata_path("golden/ouro/tiny");
    if !dir.join("golden.safetensors").exists() {
        brain_testutil::skip("testdata/golden/ouro/tiny absent (run tools/goldens/ouro_dump_reference.py)");
        return;
    }
    let (cfg, src) = ouro::import::open_dir(&dir.join("checkpoint")).expect("open tiny ouro checkpoint");
    let model = Ouro::new(cfg.clone(), 1, 4, &src);
    model.set_tokens(&[3, 4, 5, 6]);
    model.trunk_forward();
    // Released threshold 1.0: the normalized mass reaches 1 only on the final
    // pass, so every row exits there.
    assert_eq!(model.exit_steps(), vec![cfg.total_ut_steps - 1; 4]);
}
